INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch08$PT142-S1-Q1$batch08$, 142, 1, 1, $batch08$Most Strongly Supported$batch08$, $batch08$Children should be discouraged from reading Jones’s books. Reading them is like eating candy, which provides intense, short-term sensory stimulation but leaves one poorly nourished and dulls one’s taste for better fare. In other words, the problem with letting children read Jones’s books is that _______.$batch08$, $batch08$Which one of the following most logically completes the argument above?$batch08$, $batch08$C$batch08$, true, $batch08$Batch 08; question text from local bank.$batch08$ FROM lr_sections s WHERE s.preptest=142 AND s.section=1 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch08$PT142-S1-Q1$batch08$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch08$A$batch08$, $batch08$it will lead them to develop a taste for candy and sweets$batch08$, $batch08$Out of Scope$batch08$, false FROM lr_questions q WHERE q.qid=$batch08$PT142-S1-Q1$batch08$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch08$A$batch08$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch08$B$batch08$, $batch08$too many children may become frustrated by their difficulty and stop reading altogether$batch08$, $batch08$Opposite$batch08$, false FROM lr_questions q WHERE q.qid=$batch08$PT142-S1-Q1$batch08$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch08$B$batch08$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch08$C$batch08$, $batch08$their doing so interferes with the development of appreciation for more challenging literature$batch08$, $batch08$Correct$batch08$, true FROM lr_questions q WHERE q.qid=$batch08$PT142-S1-Q1$batch08$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch08$C$batch08$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch08$D$batch08$, $batch08$their message may undermine the positive teaching done by parents$batch08$, $batch08$Out of Scope$batch08$, false FROM lr_questions q WHERE q.qid=$batch08$PT142-S1-Q1$batch08$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch08$D$batch08$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch08$E$batch08$, $batch08$children may become so enthralled with books that they will want to spend all their time reading$batch08$, $batch08$Out of Scope$batch08$, false FROM lr_questions q WHERE q.qid=$batch08$PT142-S1-Q1$batch08$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch08$E$batch08$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch08$PT142-S1-Q1$batch08$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch08$Statements$batch08$, $batch08$Children shouldn't read Jones's books. Reading them is like eating candy: a strong, quick thrill that leaves you poorly nourished and dulls your taste for better food.$batch08$), (1, $batch08$Evaluate$batch08$, $batch08$The blank starts "In other words", so it restates the analogy in plain terms. Map each piece: candy = Jones's books, poor nourishment = not much to gain, a dulled taste for better fare = less appetite for better books.$batch08$), (2, $batch08$Goal$batch08$, $batch08$Reading Jones dulls children's taste for better books.$batch08$)) v(position,label,body) WHERE q.qid=$batch08$PT142-S1-Q1$batch08$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch08$A$batch08$, $batch08$The candy is a comparison. Nobody says the books make children want actual sweets.$batch08$), ($batch08$B$batch08$, $batch08$Candy is easy and pleasant. The analogy suggests the books are too easy, not too hard.$batch08$), ($batch08$C$batch08$, $batch08$"Dulls one's taste for better fare" maps onto interfering with appreciation of more challenging literature.$batch08$), ($batch08$D$batch08$, $batch08$The books' message and parents' teaching never come up.$batch08$), ($batch08$E$batch08$, $batch08$The worry is which books children come to like, not reading too much.$batch08$)) v(letter,body) WHERE q.qid=$batch08$PT142-S1-Q1$batch08$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
